#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\nimport sys\nimport json\nimport sqlite3\nfrom pathlib import Path\nfrom uuid import uuid4\nfrom datetime import datetime\nfrom threading import Thread\nimport asyncio\n\nfrom PyQt6.QtWidgets import (\n    QApplication, QMainWindow, QWidget, QVBoxLayout, QHBoxLayout,\n    QPushButton, QLabel, QLineEdit, QFileDialog, QListWidget,\n    QListWidgetItem, QDialog, QMessageBox, QInputDialog\n)\nfrom PyQt6.QtCore import Qt, QTimer, pyqtSignal, QObject, QThread\nfrom PyQt6.QtGui import QPixmap, QIcon, QColor\nfrom PyQt6.QtWidgets import QScrollArea\n\nfrom fastapi import FastAPI, WebSocket, WebSocketDisconnect\nfrom fastapi.responses import JSONResponse\nimport uvicorn\n\n# Database setup\nDB_PATH = Path(\"devices.db\")\n\ndef init_db():\n    conn = sqlite3.connect(DB_PATH)\n    cursor = conn.cursor()\n    cursor.execute(\"\"\"\n        CREATE TABLE IF NOT EXISTS devices (\n            device_id TEXT PRIMARY KEY,\n            device_name TEXT,\n            nickname TEXT,\n            photo_path TEXT,\n            status TEXT,\n            token TEXT,\n            created_at TEXT\n        )\n    \"\"\")\n    conn.commit()\n    conn.close()\n\ndef get_db():\n    conn = sqlite3.connect(DB_PATH)\n    conn.row_factory = sqlite3.Row\n    return conn\n\n# FastAPI Server\napp = FastAPI(title=\"Remote Control Server\")\nconnected_clients = {}\n\n@app.get(\"/\")\nasync def root():\n    return {\"status\": \"ok\", \"message\": \"Remote control server is running\"}\n\n@app.post(\"/devices/register\")\nasync def register_device(device_name: str, nickname: str, photo_path: str = \"\"):\n    device_id = str(uuid4())\n    token = str(uuid4())\n    created_at = datetime.utcnow().isoformat()\n    \n    conn = get_db()\n    cursor = conn.cursor()\n    cursor.execute(\n        \"INSERT INTO devices (device_id, device_name, nickname, photo_path, status, token, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)\",\n        (device_id, device_name, nickname, photo_path, \"offline\", token, created_at)\n    )\n    conn.commit()\n    conn.close()\n    \n    return {\n        \"device_id\": device_id,\n        \"token\": token,\n        \"message\": \"Device registered successfully\"\n    }\n\n@app.get(\"/devices\")\nasync def list_devices():\n    conn = get_db()\n    cursor = conn.cursor()\n    cursor.execute(\"SELECT device_id, device_name, nickname, photo_path, status, token FROM devices\")\n    rows = cursor.fetchall()\n    conn.close()\n    \n    devices = []\n    for row in rows:\n        devices.append({\n            \"device_id\": row[0],\n            \"device_name\": row[1],\n            \"nickname\": row[2],\n            \"photo_path\": row[3],\n            \"status\": row[4],\n            \"token\": row[5]\n        })\n    \n    return devices\n\n@app.websocket(\"/ws/{device_id}\")\nasync def websocket_endpoint(websocket: WebSocket, device_id: str):\n    await websocket.accept()\n    connected_clients[device_id] = websocket\n    \n    conn = get_db()\n    cursor = conn.cursor()\n    cursor.execute(\"UPDATE devices SET status = ? WHERE device_id = ?\", (\"online\", device_id))\n    conn.commit()\n    conn.close()\n    \n    try:\n        while True:\n            data = await websocket.receive_text()\n            print(f\"[Device {device_id}] {data}\")\n    except WebSocketDisconnect:\n        connected_clients.pop(device_id, None)\n        conn = get_db()\n        cursor = conn.cursor()\n        cursor.execute(\"UPDATE devices SET status = ? WHERE device_id = ?\", (\"offline\", device_id))\n        conn.commit()\n        conn.close()\n\n# Server Runner\nclass ServerRunner(QObject):\n    finished = pyqtSignal()\n    \n    def run_server(self):\n        loop = asyncio.new_event_loop()\n        asyncio.set_event_loop(loop)\n        config = uvicorn.Config(app, host=\"127.0.0.1\", port=8000, log_level=\"critical\")\n        server = uvicorn.Server(config)\n        loop.run_until_complete(server.serve())\n\n# Main GUI\nclass RemoteControlApp(QMainWindow):\n    def __init__(self):\n        super().__init__()\n        init_db()\n        \n        self.setWindowTitle(\"Remote Control - PC\")\n        self.setGeometry(100, 100, 1000, 700)\n        self.setStyleSheet(self.get_dark_stylesheet())\n        \n        # Start server in thread\n        self.server_thread = QThread()\n        self.server_runner = ServerRunner()\n        self.server_runner.moveToThread(self.server_thread)\n        self.server_thread.started.connect(self.server_runner.run_server)\n        self.server_thread.start()\n        \n        # Main widget\n        central = QWidget()\n        self.setCentralWidget(central)\n        layout = QHBoxLayout()\n        \n        # Left panel - Device list\n        left_panel = QVBoxLayout()\n        left_panel.addWidget(QLabel(\"📱 Seus Dispositivos\"))\n        \n        self.device_list = QListWidget()\n        self.device_list.itemClicked.connect(self.on_device_selected)\n        left_panel.addWidget(self.device_list)\n        \n        btn_add = QPushButton(\"➕ Adicionar Dispositivo\")\n        btn_add.clicked.connect(self.add_device_dialog)\n        left_panel.addWidget(btn_add)\n        \n        btn_refresh = QPushButton(\"🔄 Atualizar\")\n        btn_refresh.clicked.connect(self.refresh_devices)\n        left_panel.addWidget(btn_refresh)\n        \n        # Right panel - Device details\n        right_panel = QVBoxLayout()\n        right_panel.addWidget(QLabel(\"ℹ️ Detalhes do Dispositivo\"))\n        \n        self.device_info = QLabel(\"Selecione um dispositivo\")\n        self.device_info.setAlignment(Qt.AlignmentFlag.AlignTop)\n        self.device_info.setWordWrap(True)\n        right_panel.addWidget(self.device_info)\n        \n        btn_connect = QPushButton(\"🔗 Conectar e Visualizar\")\n        btn_connect.clicked.connect(self.connect_device)\n        right_panel.addWidget(btn_connect)\n        \n        btn_remove = QPushButton(\"🗑️ Remover Dispositivo\")\n        btn_remove.clicked.connect(self.remove_device)\n        right_panel.addWidget(btn_remove)\n        \n        # Add panels to main layout\n        left_container = QWidget()\n        left_container.setLayout(left_panel)\n        \n        right_container = QWidget()\n        right_container.setLayout(right_panel)\n        \n        layout.addWidget(left_container, 1)\n        layout.addWidget(right_container, 1)\n        \n        central.setLayout(layout)\n        \n        # Refresh timer\n        self.refresh_timer = QTimer()\n        self.refresh_timer.timeout.connect(self.refresh_devices)\n        self.refresh_timer.start(2000)\n        \n        self.selected_device = None\n        self.refresh_devices()\n    \n    def get_dark_stylesheet(self):\n        return \"\"\"\n            QMainWindow {\n                background-color: #1e1e1e;\n                color: #ffffff;\n            }\n            QPushButton {\n                background-color: #0078d4;\n                color: white;\n                border: none;\n                padding: 8px;\n                border-radius: 4px;\n                font-weight: bold;\n            }\n            QPushButton:hover {\n                background-color: #106ebe;\n            }\n            QLineEdit {\n                background-color: #2d2d2d;\n                color: white;\n                border: 1px solid #0078d4;\n                padding: 5px;\n                border-radius: 3px;\n            }\n            QListWidget {\n                background-color: #2d2d2d;\n                color: white;\n                border: 1px solid #0078d4;\n                border-radius: 3px;\n            }\n            QLabel {\n                color: #ffffff;\n            }\n        \"\"\"\n    \n    def add_device_dialog(self):\n        device_name, ok = QInputDialog.getText(self, \"Novo Dispositivo\", \"Nome do dispositivo:\")\n        if not ok or not device_name:\n            return\n        \n        nickname, ok = QInputDialog.getText(self, \"Novo Dispositivo\", \"Apelido (opcional):\")\n        if not ok:\n            return\n        \n        photo_path, _ = QFileDialog.getOpenFileName(\n            self, \"Selecione uma foto (opcional)\", \"\", \"Images (*.png *.jpg *.jpeg)\"\n        )\n        \n        device_id = str(uuid4())\n        token = str(uuid4())\n        created_at = datetime.utcnow().isoformat()\n        \n        conn = get_db()\n        cursor = conn.cursor()\n        cursor.execute(\n            \"INSERT INTO devices (device_id, device_name, nickname, photo_path, status, token, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)\",\n            (device_id, device_name, nickname or device_name, photo_path, \"offline\", token, created_at)\n        )\n        conn.commit()\n        conn.close()\n        \n        QMessageBox.information(\n            self,\n            \"Dispositivo Adicionado\",\n            f\"Token: {token}\\n\\nUse este token no app Android para emparelhar.\"\n        )\n        \n        self.refresh_devices()\n    \n    def refresh_devices(self):\n        self.device_list.clear()\n        \n        conn = get_db()\n        cursor = conn.cursor()\n        cursor.execute(\"SELECT device_id, device_name, nickname, status, photo_path FROM devices\")\n        devices = cursor.fetchall()\n        conn.close()\n        \n        for device in devices:\n            device_id, device_name, nickname, status, photo_path = device\n            status_icon = \"🟢\" if status == \"online\" else \"🔴\"\n            item_text = f\"{status_icon} {nickname} ({device_name})\"\n            \n            item = QListWidgetItem(item_text)\n            item.setData(Qt.ItemDataRole.UserRole, device_id)\n            self.device_list.addItem(item)\n    \n    def on_device_selected(self, item):\n        device_id = item.data(Qt.ItemDataRole.UserRole)\n        self.selected_device = device_id\n        \n        conn = get_db()\n        cursor = conn.cursor()\n        cursor.execute(\"SELECT device_name, nickname, status, token, photo_path FROM devices WHERE device_id = ?\", (device_id,))\n        row = cursor.fetchone()\n        conn.close()\n        \n        if row:\n            device_name, nickname, status, token, photo_path = row\n            info_text = f\"\"\"\n            Nome: {device_name}\n            Apelido: {nickname}\n            Status: {'🟢 Online' if status == 'online' else '🔴 Offline'}\n            Token: {token}\n            \n            Para emparelhar:\n            1. Instale o app Android\n            2. Use o token acima\n            3. Confirme a conexão no celular\n            \"\"\"\n            self.device_info.setText(info_text)\n    \n    def connect_device(self):\n        if not self.selected_device:\n            QMessageBox.warning(self, \"Erro\", \"Selecione um dispositivo primeiro.\")\n            return\n        \n        conn = get_db()\n        cursor = conn.cursor()\n        cursor.execute(\"SELECT status FROM devices WHERE device_id = ?\", (self.selected_device,))\n        row = cursor.fetchone()\n        conn.close()\n        \n        if row and row[0] == \"online\":\n            QMessageBox.information(self, \"Conectado\", \"Dispositivo conectado! A visualização da tela será implementada em breve.\")\n        else:\n            QMessageBox.warning(self, \"Offline\", \"Dispositivo desconectado. Certifique-se de que o app Android está rodando.\")\n    \n    def remove_device(self):\n        if not self.selected_device:\n            QMessageBox.warning(self, \"Erro\", \"Selecione um dispositivo primeiro.\")\n            return\n        \n        reply = QMessageBox.question(self, \"Confirmar\", \"Remover este dispositivo?\")\n        if reply == QMessageBox.StandardButton.Yes:\n            conn = get_db()\n            cursor = conn.cursor()\n            cursor.execute(\"DELETE FROM devices WHERE device_id = ?\", (self.selected_device,))\n            conn.commit()\n            conn.close()\n            \n            self.selected_device = None\n            self.device_info.setText(\"Selecione um dispositivo\")\n            self.refresh_devices()\n\nif __name__ == \"__main__\":\n    app_instance = QApplication(sys.argv)\n    window = RemoteControlApp()\n    window.show()\n    sys.exit(app_instance.exec())\n"